window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["azure-ai"]=[{"id":"azure-ai-f0001","card":"q-azure-ai-001-1-big-picture","sec":"azure-ai-s002","q":"What are Azure AI Services?","a":"<p>Pre-built AI APIs. No AI background is needed: you only call an API (REST or SDK for .NET, Node.js, Python).</p>","hand":true},{"id":"azure-ai-f0002","card":"q-azure-ai-001-1-big-picture","sec":"azure-ai-s002","q":"Which services are in the Azure AI Services family?","a":"<p>Vision, Speech, Language, Search, Content Safety, Translator and Document Intelligence, plus Azure AI Foundry for building with models.</p>","hand":true},{"id":"azure-ai-f0003","card":"q-azure-ai-001-1-big-picture","sec":"azure-ai-s002","q":"What is the common pattern for every Azure AI Services demo?","a":"<ol>\n  <li>Create the resource in Azure Portal (Free tier is fine for dev).</li>\n  <li>Under Resource Management -&gt; <strong>Keys and Endpoint</strong>, copy a key and the endpoint (or region).</li>\n  <li>Put the key/endpoint in <code>.env</code>, load it with <code>dotenv</code>, and call the SDK client.</li>\n</ol>","hand":true},{"id":"azure-ai-f0004","card":"q-azure-ai-001-1-big-picture","sec":"azure-ai-s002","q":"Why does an Azure AI resource have two keys?","a":"<p>So you can rotate one key without downtime.</p>","hand":true},{"id":"azure-ai-f0005","card":"q-azure-ai-001-1-big-picture","sec":"azure-ai-s002","q":"What are the three levels of AI in Azure: AI Services, AI Solutions and AI Models?","a":"<p><strong>AI Services</strong>: pre-built cloud APIs you call and use (Vision, Speech, Language...). <strong>AI Solutions</strong>: build on models others made (fine-tuning, distillation), such as LLMs and text-to-image. <strong>Foundry</strong> sits here. <strong>AI Models</strong>: train models from scratch (petabytes, huge clusters), as Meta, Google and Microsoft do.</p>","hand":true},{"id":"azure-ai-f0006","card":"q-azure-ai-002-2-vision","sec":"azure-ai-s003","q":"What does an Azure Vision service take as input and return?","a":"<p>It takes an image (data or URL) and returns structured information.</p>","hand":true},{"id":"azure-ai-f0007","card":"q-azure-ai-002-2-vision","sec":"azure-ai-s003","q":"What are the Azure Vision services?","a":"<p>OCR, Image Analysis, Face, Spatial Analysis (video) and Video Retrieval.</p>","hand":true},{"id":"azure-ai-f0008","card":"q-azure-ai-002-2-vision","sec":"azure-ai-s003","q":"What does Azure Spatial Analysis do?","a":"<p>It works on video: counts people and measures distances (social distancing).</p>","hand":true},{"id":"azure-ai-f0009","card":"q-azure-ai-002-2-vision","sec":"azure-ai-s003","q":"What does Azure Video Retrieval do?","a":"<p>It indexes videos/images so you can search them with natural language.</p>","hand":true},{"id":"azure-ai-f0010","card":"q-azure-ai-002-2-vision","sec":"azure-ai-s003","q":"What do Azure OCR, Image Analysis and Face do?","a":"<p>OCR extracts printed or handwritten text (receipts, signs, labels). Image Analysis returns captions, objects, brands, landmarks, adult content and faces. Face detects, recognizes and analyzes faces.</p>","hand":true},{"id":"azure-ai-f0011","card":"q-azure-ai-003-ocr","sec":"azure-ai-s004","q":"What kinds of text can Azure OCR read?","a":"<p>Printed and handwritten text, in many languages, including mixed languages and mixed mode.</p>","hand":true},{"id":"azure-ai-f0012","card":"q-azure-ai-003-ocr","sec":"azure-ai-s004","q":"How can you deploy Azure OCR?","a":"<p>As a cloud API or as an on-premises container (Edge).</p>","hand":true},{"id":"azure-ai-f0013","card":"q-azure-ai-003-ocr","sec":"azure-ai-s004","q":"What does Azure OCR return for multi-page input?","a":"<p>Multi-page input (PDF, TIFF) returns multiple pages.</p>","hand":true},{"id":"azure-ai-f0014","card":"q-azure-ai-003-ocr","sec":"azure-ai-s004","q":"What does the Azure OCR result contain, and why use the confidence score?","a":"<p>Text, words and lines, each with a <strong>bounding polygon</strong> and a <strong>confidence score</strong>. Text may be occluded or overlapping, so use confidence to judge reliability.</p>","hand":true},{"id":"azure-ai-f0015","card":"q-azure-ai-003-ocr","sec":"azure-ai-s004","q":"What is the structure of an Azure OCR response?","a":"<p>Pages in <code>readResults[]</code>, each with <code>lines[]</code> (with <code>boundingBox</code>) and each line with <code>words[]</code>, where each word has <code>text</code>, <code>boundingBox</code> and <code>confidence</code> (0-1).</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>readResults[]            (pages)\n  └── lines[]\n        ├── boundingBox\n        └── words[]\n              ├── text\n              ├── boundingBox\n              └── confidence (0-1)</code></pre></div>","hand":true},{"id":"azure-ai-f0016","card":"q-azure-ai-004-image-analysis","sec":"azure-ai-s005","q":"What are the detection capabilities of Azure Image Analysis?","a":"<p>People (bounding box + confidence), objects, faces, celebrities, landmarks and brands.</p>","hand":true},{"id":"azure-ai-f0017","card":"q-azure-ai-004-image-analysis","sec":"azure-ai-s005","q":"What are the analysis capabilities of Azure Image Analysis?","a":"<p>Captioning (for example \"a dog sticking its head out of a window\"), OCR, tagging, image type (line art, clip art) and color scheme.</p>","hand":true},{"id":"azure-ai-f0018","card":"q-azure-ai-004-image-analysis","sec":"azure-ai-s005","q":"What other capabilities does Azure Image Analysis have?","a":"<p>Content moderation (adult, racy, gory) and smart cropping (thumbnails).</p>","hand":true},{"id":"azure-ai-f0019","card":"q-azure-ai-004-image-analysis","sec":"azure-ai-s005","q":"How do you use Azure Image Analysis?","a":"<p>Provision a Vision resource, call the API with the image and key (the image must meet size/format limits), and specify in the request what to return.</p>","hand":true},{"id":"azure-ai-f0020","card":"q-azure-ai-005-custom-vision-build-your-own-models","sec":"azure-ai-s006","q":"What does Azure Custom Vision let you do?","a":"<p>Build your own vision models.</p>","hand":true},{"id":"azure-ai-f0021","card":"q-azure-ai-005-custom-vision-build-your-own-models","sec":"azure-ai-s006","q":"What is the difference between Image Classification and Object Detection in Azure Custom Vision?","a":"<p>Image Classification gives one or more labels for the whole image. Object Detection gives labels plus coordinates of where each is found.</p>","hand":true},{"id":"azure-ai-f0022","card":"q-azure-ai-006-face-service","sec":"azure-ai-s007","q":"Who can access the Azure Face service?","a":"<p>Access is <strong>limited</strong>: only Microsoft managed customers and partners (responsible AI). Face ID needs approval via an intake form.</p>","hand":true},{"id":"azure-ai-f0023","card":"q-azure-ai-006-face-service","sec":"azure-ai-s007","q":"What are the features of the Azure Face service?","a":"<p>Identity Verification, Liveness Detection, Touchless Access Control and Face Redaction.</p>","hand":true},{"id":"azure-ai-f0024","card":"q-azure-ai-006-face-service","sec":"azure-ai-s007","q":"What is Identity Verification and what is Liveness Detection in Azure Face?","a":"<p>Identity Verification matches a person to a trusted image (passport, license). Liveness Detection is anti-spoofing: it checks that a real person is present, not a photo, video or 3D mask.</p>","hand":true},{"id":"azure-ai-f0025","card":"q-azure-ai-006-face-service","sec":"azure-ai-s007","q":"What are Touchless Access Control and Face Redaction in Azure Face?","a":"<p>Touchless Access Control is liveness plus verification. Face Redaction blurs faces to protect privacy.</p>","hand":true},{"id":"azure-ai-f0026","card":"q-azure-ai-006-face-service","sec":"azure-ai-s007","q":"What does an Azure Face response contain?","a":"<p>An array (one image can have many faces) with <strong>Face Rectangle</strong> (left, top, width, height), <strong>Face ID</strong>, <strong>Face Landmarks</strong> and <strong>Attributes</strong>.</p>","hand":true},{"id":"azure-ai-f0027","card":"q-azure-ai-006-face-service","sec":"azure-ai-s007","q":"What are Face Landmarks and Attributes in an Azure Face response?","a":"<p>Face Landmarks are 27 points: pupils, nose tip, eyebrows, lips, ears. Attributes are accessories, blur/exposure, glasses, head pose, occlusion and mask.</p>","hand":true},{"id":"azure-ai-f0028","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"Which resource do you create in the portal for Azure handwriting recognition, and which one do you avoid?","a":"<p>Search \"vision\" and pick <strong>Computer Vision</strong>, not Custom Vision (which is for training your own models).</p>","hand":true},{"id":"azure-ai-f0029","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"What are the Free tier limits of Azure Computer Vision?","a":"<p>20 calls/min and 5,000 calls/month.</p>","hand":true},{"id":"azure-ai-f0030","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"Where are dependencies installed from in .NET, Python and Node.js?","a":"<p>NuGet in .NET, PyPI in Python, and npm packages in Node.js.</p>","hand":true},{"id":"azure-ai-f0031","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"What does the <code>.env</code> file for the Azure handwriting recognition demo contain?","a":"<p>The vision key and endpoint.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">.env</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>VISION_KEY=&quot;&lt;key&gt;&quot;\nVISION_ENDPOINT=&quot;&lt;endpoint&gt;&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0032","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"Which npm packages does the Azure handwriting recognition demo depend on?","a":"<p><code>@azure/cognitiveservices-computervision</code>, <code>dotenv</code> and <code>ms-rest-azure</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&quot;@azure/cognitiveservices-computervision&quot;: &quot;^8.2.0&quot;,\n&quot;dotenv&quot;: &quot;^16.4.5&quot;,\n&quot;ms-rest-azure&quot;: &quot;^2.5.7&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0033","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"How does the Azure handwriting demo authenticate the Computer Vision client?","a":"<p>With <code>ApiKeyCredentials</code>, using the <code>Ocp-Apim-Subscription-Key</code> header.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const computerVisionClient = new ComputerVisionClient(\n    new ApiKeyCredentials({ inHeader: { &#x27;Ocp-Apim-Subscription-Key&#x27;: key } }), endpoint);</code></pre></div>","hand":true},{"id":"azure-ai-f0034","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"In the Azure Computer Vision handwriting demo, which method submits a file stream, and which one takes a URL?","a":"<p><code>readInStream()</code> submits a file stream. Use <code>client.read()</code> for a URL.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>let operationResult = await client.readInStream(() =&gt; createReadStream(fileName));</code></pre></div>","hand":true},{"id":"azure-ai-f0035","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"Why does the Azure handwriting demo use a <code>while</code> loop?","a":"<p>The read is <strong>asynchronous</strong>: you get an <code>operationLocation</code> to poll, not results. The loop polls every second until the status is <code>succeeded</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>let operation = operationResult.operationLocation.split(&#x27;/&#x27;).slice(-1)[0];\nwhile (operationResult.status !== &quot;succeeded&quot;) {\n    await sleep(1000);\n    operationResult = await client.getReadResult(operation);\n}</code></pre></div>","hand":true},{"id":"azure-ai-f0036","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"In the Azure handwriting demo, what is <code>readResults</code>, and what does the code print for each line?","a":"<p><code>readResults</code> is an array of pages (1 for JPEG, many for PDF/TIFF). Each line prints its words joined by a space.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>console.log(line.words.map(w =&gt; w.text).join(&#x27; &#x27;));</code></pre></div>","hand":true},{"id":"azure-ai-f0037","card":"q-azure-ai-007-demo-handwriting-recognition-exercise-01","sec":"azure-ai-s008","q":"How do you run the Azure handwriting recognition demo?","a":"<p><code>node index.js</code>. It prints the recognized handwriting.</p>","hand":true},{"id":"azure-ai-f0038","card":"q-azure-ai-008-3-speech","sec":"azure-ai-s009","q":"What are the capabilities of Azure Speech?","a":"<p>Speech to Text, Text to Speech, Speaker Recognition, Intent Recognition and Translation.</p>","hand":true},{"id":"azure-ai-f0039","card":"q-azure-ai-008-3-speech","sec":"azure-ai-s009","q":"What do Azure Speech to Text, Text to Speech and Speaker Recognition do?","a":"<p>Speech to Text turns audio into searchable text. Text to Speech makes natural-sounding spoken audio. Speaker Recognition identifies who a voice belongs to.</p>","hand":true},{"id":"azure-ai-f0040","card":"q-azure-ai-008-3-speech","sec":"azure-ai-s009","q":"What do Azure Speech Intent Recognition and Translation do?","a":"<p>Intent Recognition supports voice-driven apps (\"Hey, turn the lights on\"). Translation translates speech between languages.</p>","hand":true},{"id":"azure-ai-f0041","card":"q-azure-ai-009-speech-to-text","sec":"azure-ai-s010","q":"How can you use Azure Speech to Text?","a":"<p>Batch or real-time, in many languages. Upload a file or connect an audio stream.</p>","hand":true},{"id":"azure-ai-f0042","card":"q-azure-ai-009-speech-to-text","sec":"azure-ai-s010","q":"What are the three modes of Azure Speech to Text?","a":"<p><strong>Real-time</strong>, <strong>Fast</strong> and <strong>Batch</strong>.</p>","hand":true},{"id":"azure-ai-f0043","card":"q-azure-ai-009-speech-to-text","sec":"azure-ai-s010","q":"What are Azure Speech to Text real-time mode and its use case?","a":"<p>It transcribes as audio arrives from a mic or file. Use case: live captions (e.g., UN meetings).</p>","hand":true},{"id":"azure-ai-f0044","card":"q-azure-ai-009-speech-to-text","sec":"azure-ai-s010","q":"What are Azure Speech to Text fast mode and its use case?","a":"<p>Synchronous and faster than real time. Use case: a quick transcript of a recorded interview.</p>","hand":true},{"id":"azure-ai-f0045","card":"q-azure-ai-009-speech-to-text","sec":"azure-ai-s010","q":"What are Azure Speech to Text batch mode and its use case?","a":"<p>Asynchronous, for large volumes: submit and poll. Use case: bulk audio.</p>","hand":true},{"id":"azure-ai-f0046","card":"q-azure-ai-009-speech-to-text","sec":"azure-ai-s010","q":"What are the pros and cons of out-of-the-box Azure Speech to Text vs Custom Speech?","a":"<p>Out-of-the-box: easy, fast, no training data, but weaker on domain-specific terms. Custom Speech: better accuracy for your domain, but needs training data, cost and model maintenance.</p>","hand":true},{"id":"azure-ai-f0047","card":"q-azure-ai-009-speech-to-text","sec":"azure-ai-s010","q":"What is the Azure Custom Speech workflow?","a":"<ol>\n  <li>Collect audio + transcripts.</li>\n  <li>Prepare (format, noise reduction, segmentation).</li>\n  <li>Create a model (acoustic, language, or pronunciation).</li>\n  <li>Train (hours to days).</li>\n  <li>Test on unseen data against a baseline.</li>\n  <li>Deploy via APIs/SDKs.</li>\n</ol>","hand":true},{"id":"azure-ai-f0048","card":"q-azure-ai-009-speech-to-text","sec":"azure-ai-s010","q":"When are Azure Speech base models released, and how long are they available?","a":"<p>Base models are released roughly quarterly (Jan, Apr, Jul, Oct 15th). A model is available for custom training for <strong>1 year</strong> and for transcription for <strong>2 years</strong> after release.</p>","hand":true},{"id":"azure-ai-f0049","card":"q-azure-ai-010-text-to-speech","sec":"azure-ai-s011","q":"What are the characteristics of Azure Text to Speech voices?","a":"<p>Human-like (not robotic) voices in 45+ languages and variants.</p>","hand":true},{"id":"azure-ai-f0050","card":"q-azure-ai-010-text-to-speech","sec":"azure-ai-s011","q":"What are voice roles and styles in Azure Text to Speech?","a":"<p>Cheerful, excited, whispering, newscast and affectionate.</p>","hand":true},{"id":"azure-ai-f0051","card":"q-azure-ai-010-text-to-speech","sec":"azure-ai-s011","q":"What are visemes in Azure Text to Speech?","a":"<p>A description of lip movement synced to the audio, for talking-face animation.</p>","hand":true},{"id":"azure-ai-f0052","card":"q-azure-ai-010-text-to-speech","sec":"azure-ai-s011","q":"What are the Azure Text to Speech voice options?","a":"<p><strong>Prebuilt Neural Voice</strong> (ready to use, available to all customers), <strong>Custom Neural Voice</strong> (1-2 hours of training data, represents your brand) and <strong>Personal Voice</strong> (4-6 hours of data, very natural voice of a specific person).</p>","hand":true},{"id":"azure-ai-f0053","card":"q-azure-ai-010-text-to-speech","sec":"azure-ai-s011","q":"What is needed to use Azure Custom Neural Voice and Personal Voice?","a":"<p>You must work with Microsoft (responsible-use guardrails).</p>","hand":true},{"id":"azure-ai-f0054","card":"q-azure-ai-011-speaker-recognition","sec":"azure-ai-s012","q":"What is Azure Speaker Recognition and what are its two uses?","a":"<p>It recognizes who is speaking, even a voice the system never heard before. Uses: <strong>identification</strong> (who is it?) and <strong>verification</strong> (speak to gain access).</p>","hand":true},{"id":"azure-ai-f0055","card":"q-azure-ai-011-speaker-recognition","sec":"azure-ai-s012","q":"What is the Azure Speaker Recognition flow?","a":"<p>Create an identification profile per speaker (30+ seconds of audio each). Then submit a new sample (not used to build profiles). The service returns which profiled speaker matches.</p>","hand":true},{"id":"azure-ai-f0056","card":"q-azure-ai-012-speech-translation","sec":"azure-ai-s013","q":"What are the Azure Speech Translation modes?","a":"<p>Speech -&gt; translated text, speech -&gt; translated speech, and <strong>multilingual</strong>.</p>","hand":true},{"id":"azure-ai-f0057","card":"q-azure-ai-012-speech-translation","sec":"azure-ai-s013","q":"What do speech -&gt; translated text and speech -&gt; translated speech do in Azure Speech Translation?","a":"<p>Speech -&gt; translated text: for example English audio to French text. Speech -&gt; translated speech: the listener hears their own language.</p>","hand":true},{"id":"azure-ai-f0058","card":"q-azure-ai-012-speech-translation","sec":"azure-ai-s013","q":"What is multilingual mode in Azure Speech Translation?","a":"<p>It auto-detects each input language and translates to several languages on the fly (e.g., a 5-person meeting).</p>","hand":true},{"id":"azure-ai-f0059","card":"q-azure-ai-013-intent-recognition","sec":"azure-ai-s014","q":"What is Azure Speech Intent Recognition, and what did it replace?","a":"<p>It connects spoken text to what the user wants to do. It is the successor to <strong>LUIS</strong> (deprecated, absorbed here).</p>","hand":true},{"id":"azure-ai-f0060","card":"q-azure-ai-013-intent-recognition","sec":"azure-ai-s014","q":"What are the two categories of Azure Speech Intent Recognition?","a":"<p><strong>Pattern Matching</strong> and <strong>CLU</strong> (Conversational Language Understanding).</p>","hand":true},{"id":"azure-ai-f0061","card":"q-azure-ai-013-intent-recognition","sec":"azure-ai-s014","q":"What is Pattern Matching in Azure Speech Intent Recognition?","a":"<p>Strict, accurate, fast, and works offline. No match returns an error. Examples: \"Go to floor nine\", IVR \"Press 1 for billing\".</p>","hand":true},{"id":"azure-ai-f0062","card":"q-azure-ai-013-intent-recognition","sec":"azure-ai-s014","q":"What is CLU in Azure Speech Intent Recognition?","a":"<p>Natural language: it extracts the overall intent and entities. Example: \"What is the stock price of Microsoft?\"</p>","hand":true},{"id":"azure-ai-f0063","card":"q-azure-ai-013-intent-recognition","sec":"azure-ai-s014","q":"How does CLU map different phrasings to an intent and entity?","a":"<p>Many phrasings (\"stock price of\", \"current price of\", \"trading at\") map to the same <strong>intent</strong> (<code>get_price</code>; could also be <code>buy</code>, <code>sell</code>) with an <strong>entity</strong> (<code>MSFT</code>, swappable with <code>GOOG</code>, <code>ORCL</code>).</p>","hand":true},{"id":"azure-ai-f0064","card":"q-azure-ai-013-intent-recognition","sec":"azure-ai-s014","q":"What is the CLU workflow in Azure Speech?","a":"<p>Define intents with example utterances, build a model, feed it to a recognizer, submit an utterance, and read the intent + entity.</p>","hand":true},{"id":"azure-ai-f0065","card":"q-azure-ai-013-intent-recognition","sec":"azure-ai-s014","q":"What intent and entity does CLU return for \"What is the stock price of Oracle?\"","a":"<p>Intent <code>get_price</code>, entity <code>ORCL</code>.</p>","hand":true},{"id":"azure-ai-f0066","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"Which resource do you create for the Azure Speech TTS and STT demo, and what do you copy?","a":"<p>Search \"speech\" and pick <strong>Speech</strong> (Free tier: 1 per subscription). Copy the key and <strong>region</strong> (location).</p>","hand":true},{"id":"azure-ai-f0067","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"What does the <code>.env</code> file for the Azure Speech demo contain?","a":"<p>The speech key and region.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">.env</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>SPEECH_KEY=&quot;&lt;key&gt;&quot;\nSPEECH_REGION=&quot;&lt;region&gt;&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0068","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"Which npm packages does the Azure Speech demo depend on?","a":"<p><code>microsoft-cognitiveservices-speech-sdk</code> and <code>dotenv</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&quot;microsoft-cognitiveservices-speech-sdk&quot;: &quot;^1.41.0&quot;,\n&quot;dotenv&quot;: &quot;^16.4.5&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0069","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"How do you create the <code>SpeechConfig</code> in the Azure Speech demo?","a":"<p>From the key and region with <code>fromSubscription</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const speechConfig = sdk.SpeechConfig.fromSubscription(process.env.SPEECH_KEY, process.env.SPEECH_REGION);</code></pre></div>","hand":true},{"id":"azure-ai-f0070","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"How do you set the voice and output format for Azure text to speech in the demo?","a":"<p>Set <code>speechSynthesisVoiceName</code> and <code>speechSynthesisOutputFormat</code> on the <code>SpeechConfig</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// speechConfig.speechSynthesisVoiceName = &quot;en-US-JennyNeural&quot;;\n// speechConfig.speechSynthesisOutputFormat = sdk.SpeechSynthesisOutputFormat.Audio16Khz32KBitRateMonoMp3;</code></pre></div>","hand":true},{"id":"azure-ai-f0071","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"How do you send Azure text to speech output to a file in the demo?","a":"<p>Use <code>AudioConfig.fromAudioFileOutput</code>, then a <code>SpeechSynthesizer</code> and <code>speakTextAsync</code>. The output is <code>outputaudio.wav</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// const audioConfig = sdk.AudioConfig.fromAudioFileOutput(&quot;./outputaudio.wav&quot;);\n// let synthesizer = new sdk.SpeechSynthesizer(speechConfig, audioConfig)\n// synthesizer.speakTextAsync(&quot;This is some sample text&quot;, (result) =&gt; {</code></pre></div>","hand":true},{"id":"azure-ai-f0072","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"How do you set up Azure speech to text from a WAV file in the demo?","a":"<p>Use <code>AudioConfig.fromWavFileInput</code> and a <code>SpeechRecognizer</code>, and set the recognition language.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>let audioConfig = sdk.AudioConfig.fromWavFileInput(fs.readFileSync(&quot;inputaudio.wav&quot;));\nlet speechRecognizer = new sdk.SpeechRecognizer(speechConfig, audioConfig);\nspeechConfig.speechRecognitionLanguage = &quot;en-US&quot;;</code></pre></div>","hand":true},{"id":"azure-ai-f0073","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"Which method runs a single Azure speech recognition, and what are the possible result reasons?","a":"<p><code>recognizeOnceAsync</code>. The result <code>reason</code> is <code>RecognizedSpeech</code>, <code>NoMatch</code> or <code>Canceled</code> (check <code>CancellationDetails</code>).</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>speechRecognizer.recognizeOnceAsync(result =&gt; {</code></pre></div>","hand":true},{"id":"azure-ai-f0074","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"In the Azure Speech demo, what happens when the recognition result is <code>RecognizedSpeech</code>?","a":"<p>It prints the recognized text.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>case sdk.ResultReason.RecognizedSpeech:\n    console.log(`RECOGNIZED: Text=${result.text}`);</code></pre></div>","hand":true},{"id":"azure-ai-f0075","card":"q-azure-ai-014-demo-tts-and-stt-exercise-02-07b","sec":"azure-ai-s015","q":"Which TTS and STT blocks are active in the Azure Speech demo, and what does it output?","a":"<p>The TTS block is commented out and STT is active. Swap the comments to run the other. Run <code>node index.js</code>: TTS writes <code>outputaudio.wav</code>, STT prints <code>RECOGNIZED: Text=...</code>.</p>","hand":true},{"id":"azure-ai-f0076","card":"q-azure-ai-015-4-language","sec":"azure-ai-s016","q":"What does Azure Language do?","a":"<p>It takes natural text and returns structured results. It bridges exact programs and conversational language.</p>","hand":true},{"id":"azure-ai-f0077","card":"q-azure-ai-015-4-language","sec":"azure-ai-s016","q":"What are the categories of Azure Language?","a":"<p>Extract information, Summarize, Classify, Question answering, CLU and Translate.</p>","hand":true},{"id":"azure-ai-f0078","card":"q-azure-ai-015-4-language","sec":"azure-ai-s016","q":"What does each Azure Language category do?","a":"<p>Extract information: key phrases, linked entities, NER, PII. Summarize: condense documents or conversations. Classify: sentiment, opinion mining, language detection, custom classification. Question answering: turn unstructured data into Q&amp;A. CLU: predict the intent of an utterance and extract info. Translate: between languages.</p>","hand":true},{"id":"azure-ai-f0079","card":"q-azure-ai-016-extract-information","sec":"azure-ai-s017","q":"What is key phrase extraction in Azure Language?","a":"<p>It pulls the key phrases out of text. \"I went to the doctor and got my eye prescription updated\" gives <code>doctor</code>, <code>eye prescription</code>.</p>","hand":true},{"id":"azure-ai-f0080","card":"q-azure-ai-016-extract-information","sec":"azure-ai-s017","q":"What are linked entities in Azure Language?","a":"<p>They disambiguate by linking to a knowledge base such as Wikipedia (\"Empire State Building\").</p>","hand":true},{"id":"azure-ai-f0081","card":"q-azure-ai-016-extract-information","sec":"azure-ai-s017","q":"What do NER and custom NER do in Azure Language?","a":"<p>NER identifies person, person type, location, organization, etc. Custom NER finds your own domain entities: iterate label, train, evaluate, improve.</p>","hand":true},{"id":"azure-ai-f0082","card":"q-azure-ai-016-extract-information","sec":"azure-ai-s017","q":"What does PII detection do in Azure Language?","a":"<p>It identifies, categorizes and <strong>redacts</strong> sensitive data (card numbers, names, SSNs).</p>","hand":true},{"id":"azure-ai-f0083","card":"q-azure-ai-016-extract-information","sec":"azure-ai-s017","q":"What is Text Analytics for Health?","a":"<p>NER for medical text (diagnosis, medication, symptoms, age).</p>","hand":true},{"id":"azure-ai-f0084","card":"q-azure-ai-016-extract-information","sec":"azure-ai-s017","q":"What are the sub-capabilities of Text Analytics for Health?","a":"<p>Relation Extraction, Entity Linking, Assertion Detection and Custom Text Analytics for Health.</p>","hand":true},{"id":"azure-ai-f0085","card":"q-azure-ai-016-extract-information","sec":"azure-ai-s017","q":"What do Relation Extraction and Entity Linking do in Text Analytics for Health?","a":"<p>Relation Extraction finds connections between concepts (e.g., time of condition). Entity Linking disambiguates against the UMLS Metathesaurus.</p>","hand":true},{"id":"azure-ai-f0086","card":"q-azure-ai-016-extract-information","sec":"azure-ai-s017","q":"What do Assertion Detection and Custom Text Analytics for Health do?","a":"<p>Assertion Detection finds context modifiers: certainty, conditionality, association, temporality. Custom Text Analytics for Health lets you add your own data and labels.</p>","hand":true},{"id":"azure-ai-f0087","card":"q-azure-ai-017-summarize","sec":"azure-ai-s018","q":"What is the difference between extractive and abstractive summarization in Azure Language?","a":"<p><strong>Extractive</strong> pulls key sentences from the source. <strong>Abstractive</strong> generates new sentences capturing the meaning. Text/document summarization works on text, PDF and DOCX.</p>","hand":true},{"id":"azure-ai-f0088","card":"q-azure-ai-017-summarize","sec":"azure-ai-s018","q":"What are the Azure Language conversation summarization types?","a":"<p>Recap, Issue Resolution, Chapter Title and Narrative.</p>","hand":true},{"id":"azure-ai-f0089","card":"q-azure-ai-017-summarize","sec":"azure-ai-s018","q":"What do the Recap and Issue Resolution conversation summaries do?","a":"<p>Recap: a brief paragraph of the conversation. Issue Resolution: for call centers, the issue and its resolution.</p>","hand":true},{"id":"azure-ai-f0090","card":"q-azure-ai-017-summarize","sec":"azure-ai-s018","q":"What do the Chapter Title and Narrative conversation summaries do?","a":"<p>Chapter Title: segments by topic and suggests titles. Narrative: detailed call, meeting or chat notes.</p>","hand":true},{"id":"azure-ai-f0091","card":"q-azure-ai-018-classify","sec":"azure-ai-s019","q":"What does Azure Language sentiment analysis return?","a":"<p>Negative / neutral / positive with a confidence score. \"This omelet tastes great\" is positive.</p>","hand":true},{"id":"azure-ai-f0092","card":"q-azure-ai-018-classify","sec":"azure-ai-s019","q":"What is opinion mining in Azure Language?","a":"<p>It extracts fine-grained opinions tied to specific aspects (e.g., \"great\"). Enhance it with custom labels if needed.</p>","hand":true},{"id":"azure-ai-f0093","card":"q-azure-ai-018-classify","sec":"azure-ai-s019","q":"What does Azure Language language detection return?","a":"<p>The language, and the script for languages with several scripts.</p>","hand":true},{"id":"azure-ai-f0094","card":"q-azure-ai-018-classify","sec":"azure-ai-s019","q":"What is custom text classification in Azure Language?","a":"<p>Classification with your own categories, e.g., book genre, support-ticket category, email triage.</p>","hand":true},{"id":"azure-ai-f0095","card":"q-azure-ai-019-question-answering","sec":"azure-ai-s020","q":"What is Azure Language question answering, and is it an LLM?","a":"<p>A conversational layer over <strong>your</strong> unstructured data, not an LLM answering anything. Example: processor docs, where the bot asks questions to guide the user to the right processor.</p>","hand":true},{"id":"azure-ai-f0096","card":"q-azure-ai-019-question-answering","sec":"azure-ai-s020","q":"How do you build Azure Language question answering?","a":"<p><strong>Low-code</strong>: build in a portal by uploading docs or pointing at a location (APIs exist too).</p>","hand":true},{"id":"azure-ai-f0097","card":"q-azure-ai-019-question-answering","sec":"azure-ai-s020","q":"What is multi-turn in Azure Language question answering?","a":"<p>The bot asks clarifying questions and refines the search.</p>","hand":true},{"id":"azure-ai-f0098","card":"q-azure-ai-019-question-answering","sec":"azure-ai-s020","q":"What does iterative mean in Azure Language question answering?","a":"<p>You add metadata, data, questions and tests in a loop.</p>","hand":true},{"id":"azure-ai-f0099","card":"q-azure-ai-020-clu","sec":"azure-ai-s021","q":"What does CLU do in Azure Language?","a":"<p>It extracts the overall <strong>intent</strong> of an utterance. \"What is the stock price of Microsoft?\" gives intent <code>get price</code>, entity <code>Microsoft</code>.</p>","hand":true},{"id":"azure-ai-f0100","card":"q-azure-ai-020-clu","sec":"azure-ai-s021","q":"Is CLU in Azure Language a different service from CLU in Azure Speech?","a":"<p>No. It is the same capability and service.</p>","hand":true},{"id":"azure-ai-f0101","card":"q-azure-ai-021-demo-key-phrase-extraction-exercise-03-0","sec":"azure-ai-s022","q":"Which resource do you create for the Azure key phrase extraction demo?","a":"<p>A <strong>Language Service</strong> resource (extra features can be added later under Features). Copy a key and the endpoint. Equivalent SDKs exist for .NET and Python, and REST also works.</p>","hand":true},{"id":"azure-ai-f0102","card":"q-azure-ai-021-demo-key-phrase-extraction-exercise-03-0","sec":"azure-ai-s022","q":"What does the <code>.env</code> file for the Azure key phrase extraction demo contain?","a":"<p>The language key and endpoint.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">.env</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>LANGUAGE_KEY=&quot;&quot;\nLANGUAGE_ENDPOINT=&quot;&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0103","card":"q-azure-ai-021-demo-key-phrase-extraction-exercise-03-0","sec":"azure-ai-s022","q":"Which npm packages does the Azure key phrase extraction demo depend on?","a":"<p><code>@azure/ai-text-analytics</code> and <code>dotenv</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&quot;@azure/ai-text-analytics&quot;: &quot;^5.1.0&quot;,\n&quot;dotenv&quot;: &quot;^16.4.5&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0104","card":"q-azure-ai-021-demo-key-phrase-extraction-exercise-03-0","sec":"azure-ai-s022","q":"How do you create the client in the Azure key phrase extraction demo?","a":"<p>Import <code>TextAnalyticsClient</code> and <code>AzureKeyCredential</code>, then pass the endpoint and key.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const { TextAnalyticsClient, AzureKeyCredential } = require(&quot;@azure/ai-text-analytics&quot;);\nconst client = new TextAnalyticsClient(endpoint, new AzureKeyCredential(key));</code></pre></div>","hand":true},{"id":"azure-ai-f0105","card":"q-azure-ai-021-demo-key-phrase-extraction-exercise-03-0","sec":"azure-ai-s022","q":"How do you call key phrase extraction in the Azure Language demo?","a":"<p>Call <code>client.extractKeyPhrases(documents)</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const results = client.extractKeyPhrases(documents).then((results) =&gt; {</code></pre></div>","hand":true},{"id":"azure-ai-f0106","card":"q-azure-ai-021-demo-key-phrase-extraction-exercise-03-0","sec":"azure-ai-s022","q":"What does <code>extractKeyPhrases</code> take and return in the Azure Language demo?","a":"<p>It takes an array of strings and is promise-based. It returns one result per document with an <code>id</code> and either <code>keyPhrases</code> or <code>error</code>.</p>","hand":true},{"id":"azure-ai-f0107","card":"q-azure-ai-021-demo-key-phrase-extraction-exercise-03-0","sec":"azure-ai-s022","q":"What is the output of the Azure key phrase extraction demo for \"Learning about artificial intelligence on linkedin learning can be fun.\"?","a":"<p>Document 0 with the key phrases <code>artificial intelligence</code> and <code>LinkedIn Learning</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- Document 0\n    Key phrases:\n    - artificial intelligence\n    - LinkedIn Learning</code></pre></div>","hand":true},{"id":"azure-ai-f0108","card":"q-azure-ai-022-5-search","sec":"azure-ai-s023","q":"What is Azure AI Search?","a":"<p>An <strong>enterprise-class search engine</strong> over your data, with AI added.</p>","hand":true},{"id":"azure-ai-f0109","card":"q-azure-ai-022-5-search","sec":"azure-ai-s023","q":"What are the Azure search offerings and what does each search?","a":"<p>Microsoft Search: M365 / SharePoint content. Bing Search: the open internet (or a slice). Database search: Azure SQL and Cosmos DB (full-text or vector). <strong>Azure AI Search</strong>: custom, security-protected data.</p>","hand":true},{"id":"azure-ai-f0110","card":"q-azure-ai-022-5-search","sec":"azure-ai-s023","q":"When should you use Microsoft Search, Bing Search, database search or Azure AI Search?","a":"<p>Microsoft Search: authenticated users, internal content. Bing Search: internet-facing sites. Database search: data already in a DBMS. Azure AI Search: enterprise search over your own content.</p>","hand":true},{"id":"azure-ai-f0111","card":"q-azure-ai-022-5-search","sec":"azure-ai-s023","q":"When should you choose Azure AI Search?","a":"<p>For relevance tuning, heterogeneous content, heavy indexing/query workloads, offloading search from the DBMS, or content that is neither on the internet nor in SharePoint.</p>","hand":true},{"id":"azure-ai-f0112","card":"q-azure-ai-022-5-search","sec":"azure-ai-s023","q":"How does Azure AI Search work, end to end?","a":"<p>Content from multiple places -&gt; provision the service (size, queries, indexes) -&gt; full index, then refresh crawls (changes only) -&gt; optional AI enrichment -&gt; the query engine serves apps (portal, APIs, clients).</p>","hand":true},{"id":"azure-ai-f0113","card":"q-azure-ai-023-search-types","sec":"azure-ai-s024","q":"What are the Azure AI Search types?","a":"<p>Vector, full-text and hybrid.</p>","hand":true},{"id":"azure-ai-f0114","card":"q-azure-ai-023-search-types","sec":"azure-ai-s024","q":"How does vector search work in Azure AI Search?","a":"<p>Numeric representations enable semantic likeness (cat/feline), multilingual matching (dog/hund) and cross-media matching (airplane text vs image).</p>","hand":true},{"id":"azure-ai-f0115","card":"q-azure-ai-023-search-types","sec":"azure-ai-s024","q":"How does full-text search work in Azure AI Search?","a":"<p>It uses a plain-text index: it lowercases, removes stop words (\"the\"), and reduces words to root forms.</p>","hand":true},{"id":"azure-ai-f0116","card":"q-azure-ai-023-search-types","sec":"azure-ai-s024","q":"What is hybrid search in Azure AI Search?","a":"<p>Vector + full-text run in parallel and the results are merged.</p>","hand":true},{"id":"azure-ai-f0117","card":"q-azure-ai-024-ai-enrichment","sec":"azure-ai-s025","q":"Why does Azure AI Search need AI enrichment?","a":"<p>Raw data (a PDF with images, video) must be \"cracked open\" first.</p>","hand":true},{"id":"azure-ai-f0118","card":"q-azure-ai-024-ai-enrichment","sec":"azure-ai-s025","q":"What is the Azure AI Search enrichment pipeline?","a":"<p>Data -&gt; crack documents -&gt; apply AI skill -&gt; enriched document -&gt; index -&gt; search. Example: a translation skill lets a search for \"hund\" match \"dog\".</p>","hand":true},{"id":"azure-ai-f0119","card":"q-azure-ai-024-ai-enrichment","sec":"azure-ai-s025","q":"What are built-in and custom skills in Azure AI Search?","a":"<p>Built-in skills: word meanings, OCR, entity recognition, translation, image analysis. Custom skills: call any <strong>web API</strong> (e.g., OpenAI models) or Azure Machine Learning skills.</p>","hand":true},{"id":"azure-ai-f0120","card":"q-azure-ai-024-ai-enrichment","sec":"azure-ai-s025","q":"Does the Azure AI Search free tier support cognitive skills?","a":"<p>No.</p>","hand":true},{"id":"azure-ai-f0121","card":"q-azure-ai-025-semantic-ranking","sec":"azure-ai-s026","q":"What does semantic ranking do in Azure AI Search?","a":"<p>It improves result relevance so the most relevant results are on top.</p>","hand":true},{"id":"azure-ai-f0122","card":"q-azure-ai-025-semantic-ranking","sec":"azure-ai-s026","q":"What are captions and answers in Azure AI Search semantic ranking?","a":"<p>Captions: an auto summary/title per result with the key info highlighted. Answers: a concise direct answer extracted from the best document.</p>","hand":true},{"id":"azure-ai-f0123","card":"q-azure-ai-025-semantic-ranking","sec":"azure-ai-s026","q":"What does semantic search do differently for \"What is the capital of France?\"","a":"<p>A simple search may return capital punishment in France. Semantic search ranks properly, adds captions, and answers <strong>Paris</strong>.</p>","hand":true},{"id":"azure-ai-f0124","card":"q-azure-ai-025-semantic-ranking","sec":"azure-ai-s026","q":"What is the cost and setup of Azure AI Search semantic ranking?","a":"<p>It is a <strong>premium feature</strong> (free up to 1,000 queries) and must be enabled on the instance.</p>","hand":true},{"id":"azure-ai-f0125","card":"q-azure-ai-025-semantic-ranking","sec":"azure-ai-s026","q":"How do you call semantic ranking through the Azure AI Search REST API?","a":"<p>Add <code>queryType=semantic</code> to the search request.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>GET /indexes/{index}/docs?search=capital of France&amp;queryType=semantic</code></pre></div>","hand":true},{"id":"azure-ai-f0126","card":"q-azure-ai-026-vectors","sec":"azure-ai-s027","q":"What are vector embeddings in Azure AI Search, and what are the benefits?","a":"<p>They map words, phrases or documents into a multidimensional space so similarity can be computed. Benefits: semantic similarity, finding relevant documents and ranking by relevance.</p>","hand":true},{"id":"azure-ai-f0127","card":"q-azure-ai-026-vectors","sec":"azure-ai-s027","q":"What do you add at index creation for Azure AI Search vector search?","a":"<p>A vector search section with an algorithm (<strong>HNSW</strong> or exhaustive <strong>KNN</strong>), compression, and profiles.</p>","hand":true},{"id":"azure-ai-f0128","card":"q-azure-ai-026-vectors","sec":"azure-ai-s027","q":"What compression options does Azure AI Search vector search have, and what is a profile?","a":"<p>Scalar and binary quantization, oversampling, and re-ranking with original vectors. Profiles are combinations of algorithm + compression.</p>","hand":true},{"id":"azure-ai-f0129","card":"q-azure-ai-026-vectors","sec":"azure-ai-s027","q":"How do you run a vector query in Azure AI Search?","a":"<p>POST the natural-language query to an embeddings endpoint to get a vector query, then POST that to the search endpoint.</p>","hand":true},{"id":"azure-ai-f0130","card":"q-azure-ai-027-demo-build-an-index-portal","sec":"azure-ai-s028","q":"What are the steps of the Azure AI Search portal demo?","a":"<ol>\n  <li>Create the Azure AI Search resource.</li>\n  <li>Import data.</li>\n  <li>Set index field attributes.</li>\n  <li>Create an indexer.</li>\n  <li>Verify under Search Management and test in Search Explorer.</li>\n</ol>","hand":true},{"id":"azure-ai-f0131","card":"q-azure-ai-027-demo-build-an-index-portal","sec":"azure-ai-s028","q":"Which tier is enough for Azure AI Search tests?","a":"<p>The Free tier, with limited replicas/HA.</p>","hand":true},{"id":"azure-ai-f0132","card":"q-azure-ai-027-demo-build-an-index-portal","sec":"azure-ai-s028","q":"Which data can you import in the Azure AI Search demo?","a":"<p>SQL, Blob, Cosmos DB or samples. The demo uses <code>hotels-sample</code>. Other entries: Add indexes, Import and vectorize data, Search Explorer.</p>","hand":true},{"id":"azure-ai-f0133","card":"q-azure-ai-027-demo-build-an-index-portal","sec":"azure-ai-s028","q":"What do the Azure AI Search index field attributes Retrievable, Filterable and Sortable mean?","a":"<p>Retrievable: the value is returned in results. Filterable: filter on exact values. Sortable: sort results by it.</p>","hand":true},{"id":"azure-ai-f0134","card":"q-azure-ai-027-demo-build-an-index-portal","sec":"azure-ai-s028","q":"What do the Azure AI Search index field attributes Facetable, Searchable and Suggester mean?","a":"<p>Facetable: auto facets to narrow results. Searchable: affects relevance. Suggester: autocomplete and misspelling suggestions.</p>","hand":true},{"id":"azure-ai-f0135","card":"q-azure-ai-027-demo-build-an-index-portal","sec":"azure-ai-s028","q":"How does an Azure AI Search indexer crawl, and what does incremental crawling need?","a":"<p>A full crawl first, then incremental. Incremental needs change tracking on the data source. Samples lack it, so they are one-time only.</p>","hand":true},{"id":"azure-ai-f0136","card":"q-azure-ai-027-demo-build-an-index-portal","sec":"azure-ai-s028","q":"Where do you verify an Azure AI Search index, and how do you test it?","a":"<p>Verify under Search Management (Indexes document count, Indexers status, Data Sources, Skill Sets). Test in <strong>Search Explorer</strong> (same as REST/SDK).</p>","hand":true},{"id":"azure-ai-f0137","card":"q-azure-ai-027-demo-build-an-index-portal","sec":"azure-ai-s028","q":"What do the queries <code>hotel</code> and <code>hotel with pool in New York</code> return in the Azure AI Search demo?","a":"<p><code>hotel</code> returns all hotel results. <code>hotel with pool in New York</code> returns filtered matches.</p>","hand":true},{"id":"azure-ai-f0138","card":"q-azure-ai-028-6-content-safety","sec":"azure-ai-s029","q":"What is Azure AI Content Safety?","a":"<p>A service that detects and flags harmful content.</p>","hand":true},{"id":"azure-ai-f0139","card":"q-azure-ai-028-6-content-safety","sec":"azure-ai-s029","q":"What are the capabilities of Azure AI Content Safety?","a":"<p>Prompt Shields, Protected Material Detection, Analyze Text, Analyze Image, Groundedness Detection and Custom Categories.</p>","hand":true},{"id":"azure-ai-f0140","card":"q-azure-ai-028-6-content-safety","sec":"azure-ai-s029","q":"What does Azure AI Content Safety Prompt Shields do?","a":"<p>It scans user input to LLMs to block crafted inputs (jailbreaks) that coax harmful output.</p>","hand":true},{"id":"azure-ai-f0141","card":"q-azure-ai-028-6-content-safety","sec":"azure-ai-s029","q":"What does Azure AI Content Safety Protected Material Detection do?","a":"<p>It works on text and code. For code, it detects if it was lifted from existing GitHub repos.</p>","hand":true},{"id":"azure-ai-f0142","card":"q-azure-ai-028-6-content-safety","sec":"azure-ai-s029","q":"What do Analyze Text and Analyze Image return in Azure AI Content Safety?","a":"<p>Severity scores for <strong>Hate, Self-Harm, Sexual, Violence</strong>. Analyze Image uses the same four categories for images.</p>","hand":true},{"id":"azure-ai-f0143","card":"q-azure-ai-028-6-content-safety","sec":"azure-ai-s029","q":"Can Azure AI Content Safety text be flagged in more than one category?","a":"<p>Yes. Text is scored on all four categories at once, so it can be both sexual and violent.</p>","hand":true},{"id":"azure-ai-f0144","card":"q-azure-ai-028-6-content-safety","sec":"azure-ai-s029","q":"What does Azure AI Content Safety Groundedness Detection do?","a":"<p>It checks that LLM responses are grounded in the supplied material. It has domains (medical, generic) and tasks (Q&amp;A, summarization). Detailed explanations of ungrounded parts cost speed.</p>","hand":true},{"id":"azure-ai-f0145","card":"q-azure-ai-028-6-content-safety","sec":"azure-ai-s029","q":"What do Azure AI Content Safety Custom Categories do?","a":"<p>You define categories, label data and train. A <strong>rapid version</strong> answers quickly without full retraining.</p>","hand":true},{"id":"azure-ai-f0146","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"Which resource do you create for the Azure Content Safety demo?","a":"<p><strong>Azure AI Content Safety</strong> (Free tier). Copy the key and endpoint.</p>","hand":true},{"id":"azure-ai-f0147","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"What does the <code>.env</code> file for the Azure Content Safety demo contain?","a":"<p>The content safety key and endpoint.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">.env</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>CONTENT_SAFETY_KEY=&quot;&quot;\nCONTENT_SAFETY_ENDPOINT=&quot;&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0148","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"Which npm packages does the Azure Content Safety demo depend on?","a":"<p><code>@azure-rest/ai-content-safety</code> and <code>dotenv</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&quot;@azure-rest/ai-content-safety&quot;: &quot;^1.0.0&quot;,\n&quot;dotenv&quot;: &quot;^16.4.5&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0149","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"How do you create the Azure Content Safety client in the demo?","a":"<p>Create <code>ContentSafetyClient(endpoint, AzureKeyCredential)</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const credential = new AzureKeyCredential(key);\nconst client = ContentSafetyClient(endpoint, credential);</code></pre></div>","hand":true},{"id":"azure-ai-f0150","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"How do you analyze text with the Azure Content Safety client?","a":"<p>POST <code>{ text }</code> to <code>/text:analyze</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const analyzeTextOption = { text: textContent };\nconst analyzeTextParameters = { body: analyzeTextOption };\nconst result = await client.path(&quot;/text:analyze&quot;).post(analyzeTextParameters);</code></pre></div>","hand":true},{"id":"azure-ai-f0151","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"What does <code>isUnexpected</code> do in the Azure Content Safety demo?","a":"<p>It detects error responses.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if (isUnexpected(result)) {\n    throw result;\n}</code></pre></div>","hand":true},{"id":"azure-ai-f0152","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"Where do you read the Azure Content Safety results?","a":"<p>In <code>result.body.categoriesAnalysis</code>, which holds the severity per category.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>for (let i = 0; i &lt; result.body.categoriesAnalysis.length; i++) {</code></pre></div>","hand":true},{"id":"azure-ai-f0153","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"What were the sample results of the Azure Content Safety demo?","a":"<p>Safe text scored 0 in all four categories. Hate content scored 2 for Hate. Violent content scored 4 for Violence. Sexual and self-harm content scored only in their own category.</p>","hand":true},{"id":"azure-ai-f0154","card":"q-azure-ai-029-demo-text-moderation-exercise-05-02b","sec":"azure-ai-s030","q":"Why may the output order differ from submission order in the Azure Content Safety demo?","a":"<p>The calls are async.</p>","hand":true},{"id":"azure-ai-f0155","card":"q-azure-ai-030-7-translator","sec":"azure-ai-s031","q":"What does Azure Translator do?","a":"<p>It translates text or documents. Pair it with Speech for spoken translation.</p>","hand":true},{"id":"azure-ai-f0156","card":"q-azure-ai-030-7-translator","sec":"azure-ai-s031","q":"What are the capabilities of Azure Translator?","a":"<p>Text Translation, Transliteration, Document Translation and Custom Translation.</p>","hand":true},{"id":"azure-ai-f0157","card":"q-azure-ai-030-7-translator","sec":"azure-ai-s031","q":"What is Azure Translator Text Translation?","a":"<p>It translates, transliterates and detects language.</p>","hand":true},{"id":"azure-ai-f0158","card":"q-azure-ai-030-7-translator","sec":"azure-ai-s031","q":"What is Azure Translator Transliteration?","a":"<p>The same language in another script (Hindi in Latin characters).</p>","hand":true},{"id":"azure-ai-f0159","card":"q-azure-ai-030-7-translator","sec":"azure-ai-s031","q":"What are Azure Translator Document Translation and Custom Translation?","a":"<p>Document Translation: sync or async, multiple file types, via REST. Custom Translation: domain terminology, and it requires training.</p>","hand":true},{"id":"azure-ai-f0160","card":"q-azure-ai-030-7-translator","sec":"azure-ai-s031","q":"What are the Azure Translator deployment options?","a":"<p><strong>Cloud</strong>: provision in the Portal and call with a key; needs internet. <strong>Edge (offline container)</strong>: host on your infrastructure, for ships and remote sites.</p>","hand":true},{"id":"azure-ai-f0161","card":"q-azure-ai-031-demo-text-translation-exercise-06-02b","sec":"azure-ai-s032","q":"Which resource do you create for the Azure Translator demo, and what must you copy?","a":"<p>A <strong>Translator</strong> resource (Free tier). Copy the key, endpoint and <strong>region</strong>. The region is required in the credential.</p>","hand":true},{"id":"azure-ai-f0162","card":"q-azure-ai-031-demo-text-translation-exercise-06-02b","sec":"azure-ai-s032","q":"What does the <code>.env</code> file for the Azure Translator demo contain?","a":"<p>The translator key, endpoint and region.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">.env</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>TRANSLATOR_KEY=&quot;&quot;\nTRANSLATOR_ENDPOINT=&quot;&quot;\nTRANSLATOR_REGION=&quot;eastus&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0163","card":"q-azure-ai-031-demo-text-translation-exercise-06-02b","sec":"azure-ai-s032","q":"Which npm packages does the Azure Translator demo depend on?","a":"<p><code>dotenv</code> and <code>@azure-rest/ai-translation-text</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&quot;dotenv&quot;: &quot;^16.4.5&quot;,\n&quot;@azure-rest/ai-translation-text&quot;: &quot;^1.0.0&quot;</code></pre></div>","hand":true},{"id":"azure-ai-f0164","card":"q-azure-ai-031-demo-text-translation-exercise-06-02b","sec":"azure-ai-s032","q":"How do you build the Azure Translator client and credential in the demo?","a":"<p>Make a credential object with the key and region, then pass it with the endpoint to <code>TextTranslationClient</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const translateCredential = {\n    key: apiKey,\n    region,\n};\nconst translationClient = new TextTranslationClient(endpoint, translateCredential);</code></pre></div>","hand":true},{"id":"azure-ai-f0165","card":"q-azure-ai-031-demo-text-translation-exercise-06-02b","sec":"azure-ai-s032","q":"What does the Azure Translator input look like?","a":"<p>An array of <code>{ text }</code> objects.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const inputText = [{ text: &quot;The world is full of miracles.&quot; }];</code></pre></div>","hand":true},{"id":"azure-ai-f0166","card":"q-azure-ai-031-demo-text-translation-exercise-06-02b","sec":"azure-ai-s032","q":"How do you call Azure Translator to translate English to Hindi?","a":"<p>POST to <code>/translate</code> with the <code>from</code> and <code>to</code> query parameters. Change <code>to</code> for <code>fr</code>, <code>de</code>, etc.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>translationClient.path(&quot;/translate&quot;).post({\n    body: inputText,\n    queryParameters: {\n        to: &quot;hi&quot;,\n        from: &quot;en&quot;,\n    },</code></pre></div>","hand":true},{"id":"azure-ai-f0167","card":"q-azure-ai-031-demo-text-translation-exercise-06-02b","sec":"azure-ai-s032","q":"What is the output of the Azure Translator demo for \"The world is full of miracles.\"?","a":"<p>The text translated to Hindi.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Text was translated to: &#x27;hi&#x27; and the result is: &#x27;दुनिया चमत्कारों से भरी है।&#x27;.</code></pre></div>","hand":true},{"id":"azure-ai-f0168","card":"q-azure-ai-031-demo-text-translation-exercise-06-02b","sec":"azure-ai-s032","q":"How does the Azure Translator SDK relate to the REST API?","a":"<p>The SDK is a thin wrapper over the REST API.</p>","hand":true},{"id":"azure-ai-f0169","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"What is Azure Document Intelligence?","a":"<p>A service that extracts key-value pairs, text and tables from documents. It goes well beyond basic OCR.</p>","hand":true},{"id":"azure-ai-f0170","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"What are the capabilities of Azure Document Intelligence?","a":"<p>Text extraction (including scanned and handwritten), form recognition, table extraction, classification, entity recognition, and search and indexing.</p>","hand":true},{"id":"azure-ai-f0171","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"What forms can Azure Document Intelligence form recognition handle?","a":"<p>W-2, W-9, 1099, driver's license, receipts and invoices.</p>","hand":true},{"id":"azure-ai-f0172","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"What do Azure Document Intelligence classification, entity recognition, and search and indexing do?","a":"<p>Classification: invoice vs contract, etc. Entity recognition: name, tax ID, phone, address. Search and indexing: works in parallel with Azure AI Search.</p>","hand":true},{"id":"azure-ai-f0173","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"What is the difference between pre-built and custom models in Azure Document Intelligence?","a":"<p>Pre-built models need no training, you just call the API (e.g., scan a passport and get all fields). Custom models are trained on your labeled data for your own forms (e.g., your invoice layout).</p>","hand":true},{"id":"azure-ai-f0174","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"What are the Azure Document Intelligence pre-built model categories?","a":"<p>Finance/services/legal, US tax, US mortgage, and PII and identity.</p>","hand":true},{"id":"azure-ai-f0175","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"Which pre-built finance, services and legal models does Azure Document Intelligence offer?","a":"<p>Bank statements, checks (amount, name, routing and account number), contracts, credit cards, invoices, pay stubs and receipts.</p>","hand":true},{"id":"azure-ai-f0176","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"Which pre-built US tax models does Azure Document Intelligence offer?","a":"<p>W-2, 1098 (mortgage interest), 1099 and 1040.</p>","hand":true},{"id":"azure-ai-f0177","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"Which pre-built US mortgage models does Azure Document Intelligence offer?","a":"<p>1003 (loan application), 1004 (appraisal), 1005 (employment verification), 1007 (loan transmittal) and Closing Disclosure.</p>","hand":true},{"id":"azure-ai-f0178","card":"q-azure-ai-032-8-document-intelligence","sec":"azure-ai-s033","q":"Which pre-built PII and identity models does Azure Document Intelligence offer?","a":"<p>Health insurance card, ID (passport, driver's license) and marriage certificate.</p>","hand":true},{"id":"azure-ai-f0179","card":"q-azure-ai-033-9-azure-ai-foundry-ai-studio-and-azure-o","sec":"azure-ai-s034","q":"What is Azure AI Foundry?","a":"<p>The enterprise platform to <strong>build, test, deploy, and manage</strong> AI apps (full MLOps/DevOps lifecycle), at ai.azure.com. It uses models from across the industry, beyond what AI Services alone offer.</p>","hand":true},{"id":"azure-ai-f0180","card":"q-azure-ai-033-9-azure-ai-foundry-ai-studio-and-azure-o","sec":"azure-ai-s034","q":"What are the steps of a typical AI project lifecycle in Azure AI Foundry?","a":"<ol>\n  <li>Data: ingest, clean, transform, visualize.</li>\n  <li>Split (e.g., 20% train / 80% validate).</li>\n  <li>Train (given these inputs, produce this output).</li>\n  <li>Validate on held-out data.</li>\n  <li>Deploy as an API protected by Entra ID, scaled with Kubernetes.</li>\n  <li>Monitor inference and loop back (more data, retrain, tweak).</li>\n</ol>","hand":true},{"id":"azure-ai-f0181","card":"q-azure-ai-033-9-azure-ai-foundry-ai-studio-and-azure-o","sec":"azure-ai-s034","q":"Can the AI project lifecycle be done visually in Azure AI Foundry?","a":"<p>Yes.</p>","hand":true},{"id":"azure-ai-f0182","card":"q-azure-ai-034-key-features","sec":"azure-ai-s035","q":"What is the Azure AI Foundry model catalog?","a":"<p>A catalog of models from OpenAI (GPT), Microsoft (Phi), Meta (Llama), Google (Gemma), and more.</p>","hand":true},{"id":"azure-ai-f0183","card":"q-azure-ai-034-key-features","sec":"azure-ai-s035","q":"What are Azure AI Foundry model benchmarks?","a":"<p>You select several models and compare them on GPT similarity, cost, accuracy, etc.</p>","hand":true},{"id":"azure-ai-f0184","card":"q-azure-ai-034-key-features","sec":"azure-ai-s035","q":"What is the Azure AI Foundry prompt catalog?","a":"<p>Templates such as Defect Detector (finds defects against a reference image), Natural Language to SQL, and Summarization.</p>","hand":true},{"id":"azure-ai-f0185","card":"q-azure-ai-034-key-features","sec":"azure-ai-s035","q":"How does Azure AI Foundry integrate with AI Services?","a":"<p>Use Content Safety to keep competitor information out of LLM answers, Translator to accept any input language, and Vision/Speech/Language alongside LLMs.</p>","hand":true},{"id":"azure-ai-f0186","card":"q-azure-ai-035-azure-openai","sec":"azure-ai-s036","q":"What is Azure OpenAI?","a":"<p>OpenAI models used through Azure and billed on your Azure subscription.</p>","hand":true},{"id":"azure-ai-f0187","card":"q-azure-ai-035-azure-openai","sec":"azure-ai-s036","q":"What are the benefits of Azure OpenAI?","a":"<p>Azure billing, resource model, ecosystem, lifecycle, security and Azure Government availability.</p>","hand":true},{"id":"azure-ai-f0188","card":"q-azure-ai-035-azure-openai","sec":"azure-ai-s036","q":"What do the Azure OpenAI benefits Azure billing, resource model and ecosystem mean?","a":"<p>Azure billing: one bill for orgs already on Microsoft. Resource model: it lives in a resource group and Azure RBAC applies. Ecosystem: AKS, Cosmos DB, Blob Storage, Log Analytics.</p>","hand":true},{"id":"azure-ai-f0189","card":"q-azure-ai-035-azure-openai","sec":"azure-ai-s036","q":"What do the Azure OpenAI benefits lifecycle, security and Azure Government mean?","a":"<p>Lifecycle: build, deploy, version and retire with Azure tooling. Security: Entra ID, managed identity, RBAC, network and port rules. Azure Government: available for government workloads.</p>","hand":true},{"id":"azure-ai-f0190","card":"q-azure-ai-035-azure-openai","sec":"azure-ai-s036","q":"How do you access Azure OpenAI, and are you limited to OpenAI models?","a":"<p>Access it via Foundry (ai.azure.com), VS Code, or other tools. You are not limited to OpenAI (Llama and others too), and you can deploy to Azure or elsewhere.</p>","hand":true},{"id":"azure-ai-f0191","card":"q-azure-ai-036-choosing-a-model","sec":"azure-ai-s037","q":"How do you choose a model in Azure AI Foundry?","a":"<p>Start from an existing model, optionally fine-tune it with your data (fine-tuned = base model + your data). Balance accuracy against cost: the most accurate model costs more compute and time. Foundry gives a sortable table and charts for comparison.</p>","hand":true},{"id":"azure-ai-f0192","card":"q-azure-ai-036-choosing-a-model","sec":"azure-ai-s037","q":"What do the model criteria Accuracy and Coherence measure?","a":"<p>Accuracy: how well predictions match actual values. Coherence: output flows naturally like human language (interpretability, consistency, robustness).</p>","hand":true},{"id":"azure-ai-f0193","card":"q-azure-ai-036-choosing-a-model","sec":"azure-ai-s037","q":"What do the model criteria Groundedness and Fluency measure?","a":"<p>Groundedness: connection to the real world (context, common sense, physical constraints). Fluency: language proficiency, natural and effortless.</p>","hand":true},{"id":"azure-ai-f0194","card":"q-azure-ai-036-choosing-a-model","sec":"azure-ai-s037","q":"What do the model criteria Relevance and Similarity measure?","a":"<p>Relevance: fit to the task, context and user needs. Similarity: closeness of the response to the source (ground truth).</p>","hand":true},{"id":"azure-ai-f0195","card":"q-azure-ai-037-popular-models","sec":"azure-ai-s038","q":"Which Meta models are listed for NLP and computer vision?","a":"<p>NLP: Llama (general LLM), OPT (translation/generation), BART (summarization). Computer vision: DALL-E (text to image), SAM (segmentation).</p>","hand":true},{"id":"azure-ai-f0196","card":"q-azure-ai-037-popular-models","sec":"azure-ai-s038","q":"Which Google models are listed for NLP?","a":"<p>BERT (understanding), Transformer-XL (long-term context), T5 (text generation) and LaBSE (multilingual sentence embeddings).</p>","hand":true},{"id":"azure-ai-f0197","card":"q-azure-ai-037-popular-models","sec":"azure-ai-s038","q":"Which Google models are listed for computer vision?","a":"<p>Inception, ResNet, MobileNet and EfficientNet (classification/recognition).</p>","hand":true},{"id":"azure-ai-f0198","card":"q-azure-ai-037-popular-models","sec":"azure-ai-s038","q":"Which Microsoft models are listed for NLP and computer vision?","a":"<p>NLP: Turing-NLG (generation), DialoGPT (conversation). Computer vision: ResNet, DenseNet (classification), SegNet (segmentation).</p>","hand":true},{"id":"azure-ai-f0199","card":"q-azure-ai-037-popular-models","sec":"azure-ai-s038","q":"What are the OpenAI o1-preview and o1-mini models for?","a":"<p>Reasoning (limited preview).</p>","hand":true},{"id":"azure-ai-f0200","card":"q-azure-ai-037-popular-models","sec":"azure-ai-s038","q":"What are the OpenAI GPT series models for?","a":"<p>Language understanding and code generation. The series is 3, 3.5, 4, 4o and 4o Audio. GPT-4 is multimodal (text + images in).</p>","hand":true},{"id":"azure-ai-f0201","card":"q-azure-ai-037-popular-models","sec":"azure-ai-s038","q":"What are OpenAI Embeddings, DALL-E and Whisper for?","a":"<p>Embeddings: text to vectors for similarity, used with vector databases. DALL-E: creates new images from prompts. Whisper: speech to text and translation, many languages, can run offline.</p>","hand":true},{"id":"azure-ai-f0202","card":"q-azure-ai-037-popular-models","sec":"azure-ai-s038","q":"Where can you find more models than the ones in Azure AI Foundry?","a":"<p>Hugging Face (huggingface.co).</p>","hand":true},{"id":"azure-ai-f0203","card":"q-azure-ai-038-demo-chat-with-your-pdf-azure-openai-ai","sec":"azure-ai-s039","q":"What are the steps of the Azure OpenAI chat with your PDF demo?","a":"<ol>\n  <li>Create an <strong>Azure OpenAI</strong> resource.</li>\n  <li><strong>Deploy</strong> <code>gpt-35-turbo</code>.</li>\n  <li>Create supporting resources: Blob Storage and Azure AI Search.</li>\n  <li><strong>Add data source</strong> with the PDF.</li>\n  <li>Chat in the <strong>Chat Playground</strong>.</li>\n</ol>","hand":true},{"id":"azure-ai-f0204","card":"q-azure-ai-038-demo-chat-with-your-pdf-azure-openai-ai","sec":"azure-ai-s039","q":"What does the Azure OpenAI resource cost in the chat with your PDF demo?","a":"<p>It is paid, so delete it when done.</p>","hand":true},{"id":"azure-ai-f0205","card":"q-azure-ai-038-demo-chat-with-your-pdf-azure-openai-ai","sec":"azure-ai-s039","q":"How do you deploy <code>gpt-35-turbo</code> in the Azure OpenAI chat with your PDF demo?","a":"<p>Deploy it from base models with default settings.</p>","hand":true},{"id":"azure-ai-f0206","card":"q-azure-ai-038-demo-chat-with-your-pdf-azure-openai-ai","sec":"azure-ai-s039","q":"Which supporting resources does the Azure OpenAI chat with your PDF demo need?","a":"<p>A <strong>Blob Storage</strong> account (LRS, standard; enable <strong>CORS</strong>) for the PDF, and <strong>Azure AI Search</strong>. Azure AI Search cannot be Free tier here. It is the most expensive part, so delete it afterward.</p>","hand":true},{"id":"azure-ai-f0207","card":"q-azure-ai-038-demo-chat-with-your-pdf-azure-openai-ai","sec":"azure-ai-s039","q":"How do you add the data source in the Azure OpenAI chat with your PDF demo?","a":"<p>Upload the PDF, pick the storage and search resources, name the index, set chunk size and API-key auth, save, and wait for ingestion.</p>","hand":true},{"id":"azure-ai-f0208","card":"q-azure-ai-038-demo-chat-with-your-pdf-azure-openai-ai","sec":"azure-ai-s039","q":"What do you get in the Chat Playground of the Azure OpenAI chat with your PDF demo?","a":"<p>Answers come with <strong>references</strong> to where in the PDF they were found. <strong>View Code</strong> shows the Python behind it, and the app can be deployed into your own apps.</p>","hand":true},{"id":"azure-ai-f0209","card":"q-azure-ai-039-course-summary","sec":"azure-ai-s040","q":"In Azure AI Services, what do Vision, Speech and Language each do?","a":"<p>Vision: tags, captions, OCR, handwriting, faces. Speech: TTS, STT, speaker ID, intent, translation. Language: sentiment, key phrases, NER, CLU, Q&amp;A, summarization.</p>","hand":true},{"id":"azure-ai-f0210","card":"q-azure-ai-039-course-summary","sec":"azure-ai-s040","q":"In Azure AI Services, what do Search, Content Safety and Translator each do?","a":"<p>Search: enterprise search with vector, semantic and AI enrichment. Content Safety: moderate text and images, shield prompts. Translator: text and document translation.</p>","hand":true},{"id":"azure-ai-f0211","card":"q-azure-ai-039-course-summary","sec":"azure-ai-s040","q":"In Azure AI Services, what do Document Intelligence and Foundry each do?","a":"<p>Document Intelligence: pre-built and custom form extraction. Foundry: industry models (OpenAI, Meta, Google) for building apps.</p>","hand":true},{"id":"azure-ai-f0212","card":"q-azure-ai-039-course-summary","sec":"azure-ai-s040","q":"Where can you learn more about Azure AI Services?","a":"<p>The Azure AI Services documentation and ai.azure.com (model and prompt catalogs).</p>","hand":true}];
